const feed=document.querySelector('#feed'), loadMore=document.querySelector('#load-more'), status=document.querySelector('#feed-status'), dialog=document.querySelector('#lightbox');
let selected='Tümü',visible=0,modalIndex=0,activePosts=posts;
const revealObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting){entry.target.classList.remove('awaiting-reveal');entry.target.classList.add('reveal-in');revealObserver.unobserve(entry.target)}}},{threshold:.06});
function addPosts(){const next=activePosts.slice(visible,visible+3); for(const p of next){const article=document.createElement('article');article.className='post awaiting-reveal';article.innerHTML=`<button class="post-image" aria-label="${p.title} Görseli büyüt"><img src="assets/post-${p.id}.jpg" alt="${p.title} ${p.caption}" loading="lazy" width="640" height="800"><span class="post-badge">${p.category.toLocaleUpperCase('tr')}</span><span class="post-open" aria-hidden="true">↗</span></button><div class="post-meta"><span>AKSU KASAP & RESTAURANT</span><span>${p.date}</span></div><h3>${p.title}</h3><p>${p.caption}</p><a class="post-instagram" href="https://www.instagram.com/reel/${p.code}/" target="_blank" rel="noopener">Instagram videosunu izle ↗</a>`;article.querySelector('button').addEventListener('click',()=>openPost(posts.indexOf(p)));feed.append(article);revealObserver.observe(article)}visible+=next.length;loadMore.hidden=visible>=activePosts.length;status.textContent=visible>=activePosts.length?'Şimdilik bizden bu kadar. Yeni anlar için Instagram’da buluşalım.':'Kaydırdıkça yeni anlar sizinle.';}
function filter(category){selected=category;activePosts=category==='Tümü'?posts:posts.filter(p=>p.category===category);visible=0;feed.replaceChildren();document.querySelectorAll('[data-filter]').forEach(b=>{const active=b.dataset.filter===category;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});addPosts();if(category==='Tümü')addPosts();}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>filter(b.dataset.filter)));
document.querySelectorAll('[data-story]').forEach(b=>b.addEventListener('click',()=>{filter(b.dataset.story);document.querySelector('#akis').scrollIntoView({behavior:'smooth'})}));
loadMore.addEventListener('click',addPosts);
new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)&&visible<activePosts.length)addPosts()},{rootMargin:'150px'}).observe(document.querySelector('#load-zone'));
function openPost(index){modalIndex=(index+posts.length)%posts.length;const p=posts[modalIndex];document.querySelector('#modal-image').src=`assets/post-${p.id}.jpg`;document.querySelector('#modal-image').alt=p.title;document.querySelector('#modal-title').textContent=p.title;document.querySelector('#modal-category').textContent=p.category;document.querySelector('#modal-caption').textContent=p.caption;document.querySelector('#modal-link').href=`https://www.instagram.com/reel/${p.code}/`;document.querySelector('#modal-count').textContent=`${modalIndex+1} / ${posts.length}`;if(!dialog.open){dialog.showModal();document.body.style.overflow='hidden'}}
function closeModal(){dialog.close();document.body.style.overflow=''}
document.querySelector('.close-modal').addEventListener('click',closeModal);dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
document.querySelector('#next').addEventListener('click',()=>openPost(modalIndex+1));document.querySelector('#previous').addEventListener('click',()=>openPost(modalIndex-1));document.addEventListener('keydown',e=>{if(!dialog.open)return;if(e.key==='ArrowRight')openPost(modalIndex+1);if(e.key==='ArrowLeft')openPost(modalIndex-1)});
const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('.header nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Menüyü kapat':'Menüyü aç');toggle.textContent=open?'✕':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Menüyü aç');toggle.textContent='☰'}));
filter('Tümü');
